<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { ArrowLeft,ArrowRight,ArrowUp,ChevronRight,Search,Plus,Upload,FolderPlus,RefreshCw,SlidersHorizontal,Info,MoreHorizontal,PanelRight,Shield,Trash2,Layers,Check,FolderTree,FolderOpen as FolderOpenIcon,History,Undo2,X } from '@lucide/vue';
import { desk,navigate,travel,safely,loadProject,addUploads,applyPreset,request,apiPath,notify,getHistoryFiles,operation,openView,restorePreview } from './store';
import { entries,bytes,nameOf,parentOf,presets,type Entry } from './model';
const uploads=ref<HTMLInputElement|null>(null),folders=ref<HTMLInputElement|null>(null);
const sort=ref('name'),ascending=ref(true),draft=ref('SYNC'),anchor=ref('');
const visible=computed(()=>{
 let rows=desk.search||desk.group?desk.files.map(f=>({...f,name:nameOf(f.path),directory:false} as Entry)):entries(desk.files,desk.directories,desk.directory);
 if(desk.search)rows=rows.filter(e=>`${e.path} ${e.displayName||''} ${e.componentId||''}`.toLowerCase().includes(desk.search.toLowerCase()));
 if(desk.group)rows=rows.filter(e=>e.optionalGroup===desk.group);
 if(desk.filter!=='all')rows=rows.filter(e=>desk.filter==='pending'?!e.published||desk.project?.preview?.changes?.some((c:any)=>c.path===e.path):e.preset===desk.filter);
 return rows.sort((a,b)=>Number(b.directory)-Number(a.directory)||(ascending.value?1:-1)*(sort.value==='size'?a.size-b.size:sort.value==='version'?String(a.version||'').localeCompare(String(b.version||'')):a.name.localeCompare(b.name,'zh-CN',{numeric:true})));
});
const selected=computed(()=>desk.selection.length===1?desk.selection[0]:null);
const group=computed(()=>desk.project?.maintenance?.optionalGroups?.find((g:any)=>g.id===desk.group));
const selectedPaths=computed(()=>new Set(desk.selection.map(e=>e.path)));
const breadcrumbs=computed(()=>desk.directory?desk.directory.split('/').map((name,i,parts)=>({name,path:parts.slice(0,i+1).join('/')})):[]);
const effective=(entry:Entry)=>entry.preset||[...(desk.project?.maintenance?.presets||[])].filter(r=>r.directory?(entry.path===r.path||entry.path.startsWith(r.path+'/')):entry.path===r.path).sort((a,b)=>Number(a.directory)-Number(b.directory)||b.path.length-a.path.length)[0]?.preset||'SYNC';
watch(()=>desk.selection.map(e=>e.path).join('|'),()=>{draft.value=desk.selection.length?effective(desk.selection[0]):'SYNC';});
function select(entry:Entry,event:MouseEvent){if(event.shiftKey&&anchor.value){const start=visible.value.findIndex(e=>e.path===anchor.value),end=visible.value.findIndex(e=>e.path===entry.path);desk.selection=visible.value.slice(Math.min(start,end),Math.max(start,end)+1);}else if(event.ctrlKey||event.metaKey){desk.selection=selectedPaths.value.has(entry.path)?desk.selection.filter(e=>e.path!==entry.path):[...desk.selection,entry];anchor.value=entry.path;}else{desk.selection=[entry];anchor.value=entry.path;}}
function order(key:string){if(sort.value===key)ascending.value=!ascending.value;else{sort.value=key;ascending.value=true;}}
function filesChanged(event:Event,folder=false){const files=[...(event.target as HTMLInputElement).files||[]];addUploads(files,folder&&!desk.directory);(event.target as HTMLInputElement).value='';}
function dropped(event:DragEvent){event.preventDefault();const files=[...event.dataTransfer?.files||[]];addUploads(files,true);}
async function saveRule(){if(desk.selection.some(e=>e.directory)){desk.dialog='preset-confirm';desk.dialogData={preset:draft.value};}else await applyPreset(draft.value);}
async function addGroup(id:string){await request(apiPath('/maintenance/group-members'),'POST',{groupId:id,items:desk.selection.map(e=>({path:e.path,directory:e.directory,modId:e.componentId})),add:true});await loadProject();notify('已加入可选内容');}
async function deleteGroup(){if(!confirm(`解散“${group.value?.title}”？文件会继续按维护方式同步。`))return;await operation(async()=>{await request(apiPath('/maintenance/group-delete'),'POST',{id:desk.group});desk.group='';await loadProject();notify('可选内容已解散，检查并发布后生效');});}
async function repair(){if(!selected.value||selected.value.directory)return;await getHistoryFiles();desk.dialogData={path:selected.value.path,mode:'ONCE',reason:'',badSha256:[]};desk.dialog='correct';}
</script>
<template>
 <div class="file-workspace-native" :class="{inspecting:desk.inspector}" @dragover.prevent @drop="dropped">
  <section class="files-main">
   <div class="file-toolbar"><div class="history-buttons"><button class="icon-button" aria-label="后退" :disabled="desk.historyIndex===0" @click="travel(-1)"><ArrowLeft :size="16"/></button><button class="icon-button" aria-label="前进" :disabled="desk.historyIndex>=desk.historyPaths.length-1" @click="travel(1)"><ArrowRight :size="16"/></button><button class="icon-button" aria-label="返回上一级" :disabled="!desk.directory" @click="navigate(parentOf(desk.directory))"><ArrowUp :size="16"/></button></div>
    <nav class="path-bar" aria-label="当前目录"><button @click="navigate('')">整合包</button><template v-for="part in breadcrumbs" :key="part.path"><ChevronRight :size="12"/><button :title="part.path" @click="navigate(part.path)">{{part.name}}</button></template></nav>
    <button class="icon-button" title="刷新文件" aria-label="刷新文件" @click="safely(loadProject)"><RefreshCw :size="15"/></button><button class="icon-button" :class="{toggled:desk.inspector}" aria-label="切换文件详情" title="文件详情" @click="desk.inspector=!desk.inspector"><PanelRight :size="16"/></button>
   </div>
   <div v-if="group" class="selection-toolbar"><strong>{{group.title}}</strong><span>{{group.defaultInstall?'默认安装':'默认不安装'}}</span><button @click="desk.dialog='group';desk.dialogData={...group}">编辑</button><button @click="safely(deleteGroup)">解散…</button><button @click="desk.group=''">显示全部</button></div>
   <div class="file-actions"><label class="file-search"><Search :size="15"/><input v-model="desk.search" placeholder="搜索文件、模组或路径" aria-label="搜索文件"></label><select v-model="desk.filter" aria-label="筛选文件"><option value="all">全部文件</option><option value="pending">待发布</option><option value="REQUIRED">强制同步</option><option value="INITIAL">首次提供</option></select><div class="actions-spacer"/><button class="accent small" @click="uploads?.click()"><Upload :size="15"/>导入文件</button><button class="icon-button" aria-label="更多导入方式" @click="desk.menu=desk.menu==='import'?'':'import'"><ChevronRight :size="14" class="rotate-down"/></button>
    <div v-if="desk.menu==='import'" class="import-menu popover"><button @click="folders?.click();desk.menu=''"><FolderPlus :size="15"/>导入文件夹</button><button @click="desk.menu='';desk.dialog='import-server';desk.dialogData={}"><FolderTree :size="15"/>从服务器导入</button><button @click="desk.menu='';desk.dialog='directory';desk.dialogData={path:[desk.directory,'新建文件夹'].filter(Boolean).join('/')}"><Plus :size="15"/>新建文件夹</button></div>
    <input ref="uploads" type="file" multiple hidden @change="filesChanged($event)"><input ref="folders" type="file" multiple webkitdirectory hidden @change="filesChanged($event,true)">
   </div>
   <div v-if="desk.selection.length>1" class="selection-toolbar"><strong>已选择 {{desk.selection.length}} 项</strong><button @click="desk.dialog='preset-confirm';desk.dialogData={preset:'SYNC'}"><Shield :size="14"/>修改维护方式</button><button @click="desk.dialog='group-members';desk.dialogData={}"><Layers :size="14"/>加入可选内容</button><button class="danger-text" @click="desk.dialog='remove'"><Trash2 :size="14"/>移出</button><button class="subtle" @click="desk.selection=[]">取消选择</button></div>
   <div class="file-table-scroll"><table class="native-file-table"><thead><tr><th class="checkbox-cell"><input type="checkbox" aria-label="选择全部文件" :checked="visible.length>0&&desk.selection.length===visible.length" @change="desk.selection=($event.target as HTMLInputElement).checked?[...visible]:[]"></th><th @click="order('name')">名称<span v-if="sort==='name'">{{ascending?'↑':'↓'}}</span></th><th>维护</th><th class="right" @click="order('size')">大小</th><th @click="order('version')">版本</th></tr></thead>
    <tbody><tr v-for="entry in visible" :key="entry.path" :class="{selected:selectedPaths.has(entry.path)}" tabindex="0" @click="select(entry,$event)" @dblclick="entry.directory?navigate(entry.path):desk.inspector=true" @contextmenu.prevent="desk.selection=[entry];desk.dialog='file-actions'" @keydown.enter="entry.directory?navigate(entry.path):desk.inspector=true"><td class="checkbox-cell"><input type="checkbox" :aria-label="`选择 ${entry.path}`" :checked="selectedPaths.has(entry.path)" @click.stop @change="desk.selection=($event.target as HTMLInputElement).checked?[...desk.selection.filter(e=>e.path!==entry.path),entry]:desk.selection.filter(e=>e.path!==entry.path)"></td>
     <td><div class="file-name"><img :src="entry.directory?'/icons/folder.svg':'/icons/file.svg'" alt=""><div><strong :title="entry.path">{{entry.displayName||entry.name}}</strong><small>{{entry.directory?`${entry.count} 个文件`:entry.componentId?entry.name:desk.search?entry.path:!entry.published?'尚未发布':''}}</small></div><i v-if="!entry.directory&&(!entry.published||desk.project?.preview?.changes?.some((c:any)=>c.path===entry.path))" class="change-dot" title="待发布变化"/></div></td>
     <td><span class="rule-label" :class="effective(entry).toLowerCase()">{{presets[effective(entry)]?.label||'普通同步'}}</span></td><td class="right subtle tabular">{{bytes(entry.size)}}</td><td class="subtle">{{entry.version||'—'}}</td></tr></tbody></table>
    <div v-if="!visible.length" class="empty-list"><Search v-if="desk.search" :size="30"/><FolderOpenIcon v-else/><strong>{{desk.search?'没有找到匹配的文件':'这个目录还没有文件'}}</strong><span>{{desk.search?'换一个名称或路径试试':'拖入文件，或使用上方的导入按钮'}}</span></div>
   </div>
   <footer class="file-list-footer"><span>{{visible.length}} 项</span><span v-if="desk.selection.length">{{desk.selection.length}} 项已选择</span><span class="actions-spacer"/><button @click="safely(()=>openView('changes','operations'))"><History :size="13"/>操作记录</button><button :disabled="desk.busy||!desk.project?.releases?.length" @click="safely(()=>restorePreview())"><Undo2 :size="13"/>恢复版本设置…</button></footer>
  </section>
  <aside v-if="desk.inspector" class="file-inspector">
   <div class="inspector-title"><strong>文件详情</strong><button class="icon-button" aria-label="关闭文件详情" @click="desk.inspector=false"><X :size="15"/></button></div>
   <div v-if="!desk.selection.length" class="inspector-empty"><img src="/icons/file.svg" alt=""><strong>选择一个文件</strong><p>查看版本、路径和维护设置。按住 Ctrl 可以选择多项。</p></div>
   <template v-else><div class="inspector-identity"><img :src="selected?.directory?'/icons/folder.svg':'/icons/file.svg'" alt=""><strong>{{selected?.displayName||selected?.name||`${desk.selection.length} 项内容`}}</strong><small>{{selected?.directory?'文件夹':selected?.componentId?'Minecraft 模组':'托管文件'}}</small></div>
    <dl class="metadata-list"><template v-if="selected"><dt>路径</dt><dd class="full-path">{{selected.path}}</dd><dt>大小</dt><dd>{{bytes(selected.size)}}</dd><template v-if="selected.version"><dt>版本</dt><dd>{{selected.version}}</dd></template><template v-if="selected.componentId"><dt>模组 ID</dt><dd>{{selected.componentId}}</dd></template></template><template v-else><dt>选择数量</dt><dd>{{desk.selection.length}} 项</dd><dt>总大小</dt><dd>{{bytes(desk.selection.reduce((n,e)=>n+e.size,0))}}</dd></template></dl>
    <section class="inspector-section"><h3>维护方式</h3><label v-for="(preset,key) in presets" v-show="key!=='DEFAULT_CONFIG'||draft==='DEFAULT_CONFIG'" :key="key" class="preset-option" :class="{active:draft===key}"><input v-model="draft" type="radio" :value="key"><div><strong>{{preset.label}}</strong><small>{{preset.description}}</small></div></label><p v-if="selected?.presetSource" class="inspector-help">规则来源：{{selected.presetSource}}</p><button class="accent full" :disabled="desk.busy" @click="safely(saveRule)">保存维护设置</button></section>
    <section class="inspector-section"><h3>可选内容</h3><span v-if="selected?.optionalGroup" class="rule-label">{{desk.project?.maintenance?.optionalGroups?.find((g:any)=>g.id===selected?.optionalGroup)?.title||selected?.optionalGroup}}</span><button class="text-action" @click="desk.dialog='group-members';desk.dialogData={}"><Layers :size="14"/>加入可选内容…</button><button v-if="selected?.optionalGroup" class="text-action" @click="safely(async()=>{await request(apiPath('/maintenance/group-members'),'POST',{groupId:selected?.optionalGroup,items:desk.selection.map(e=>({path:e.path,directory:e.directory,modId:e.componentId})),add:false});await loadProject();})">从可选内容移出</button></section>
    <div class="inspector-bottom"><button class="text-action" @click="safely(()=>applyPreset(null))">继承上级维护设置</button><button v-if="selected&&!selected.directory" class="text-action" @click="safely(repair)"><Shield :size="14"/>修复玩家副本…</button><button class="text-action danger-text" @click="desk.dialog='remove'"><Trash2 :size="14"/>移出所选内容…</button></div>
   </template>
  </aside>
 </div>
</template>
